h=sha((L/'reservation.json').read_bytes()); assert h=='df096d6a132ef9b8979807aa56e30b49f77b2dadace0b042508ba8acdd29dcbc'; js('reservation-after.json',dict(utc=run,sha256=h,exact_count=20,unchanged=True,ids=R['ids']))
